  "BEUTEL {n}/{max}": "SAC {n}/{max}",
  "Fällst du in den Verlorenen Landen, rettet dein Begleiter, was in seinem Beutel liegt. Seltenere Arten tragen mehr, das Talent „Große Taschen“ gibt weitere Plätze.": "Si tu tombes dans les Terres perdues, ton compagnon sauve ce que contient sa sacoche. Les espèces plus rares portent davantage, et le talent « Grandes poches » ajoute des places.",
  "Alles herausnehmen": "Tout reprendre",
  "Verletzt – ruht sich im Versteck aus. Wieder fit in {t}.": "Blessé – se repose au repaire. De nouveau en forme dans {t}.",
  "Heiltrank geben": "Donner une potion",
