  "Pausiert – braucht Pflege": "En pause – a besoin de soins",
  "EIER {n}/{max}": "ŒUFS {n}/{max}",
  "Noch keine Eier. Das erste gibt es vom ersten Boss der Geschichte, weitere von Bossen, der Drachentruhe, aus den Verlorenen Landen und vom Basar.": "Pas encore d'œufs. Le premier vient du premier boss de l'histoire, les suivants des boss, du Coffre du dragon, des Terres perdues et du bazar.",
  "Zum Brutnest": "Vers le nid",
