  "Alle Arten entdeckt!": "Toutes les espèces découvertes!",
  "HYBRIDE {n}/{max}": "HYBRIDES {n}/{max}",
  "Gibt es nur aus der Zucht – das Zuchtbuch verrät, wer zusammenpasst.": "Uniquement par l'élevage – le livre d'élevage révèle qui va avec qui.",
