  "Schaden {d} ({p} deiner Waffe), alle {s} s.": "Dégâts {d} ({p} de ton arme), toutes les {s} s.",
  "Zieht Münzen, Material und Edelsteine aus {r} Schritt Entfernung zu dir.": "Attire l'or, les matériaux et les gemmes dans un rayon de {r} pas.",
  "Jetzt: {now}. Bei LV 100: {max}.": "Actuel : {now}. Au LV 100 : {max}.",
