  "Alle {s} s.": "Toutes les {s} s.",
  "Spezialangriff ×1,5 und alle 16 s, leuchtende Aura, ein Beutelplatz mehr.": "Attaque spéciale ×1,5 et toutes les 16 s, aura lumineuse, une place de sac en plus.",
  "Spezialangriff ×2 und alle 12 s, goldene Gestalt.": "Attaque spéciale ×2 et toutes les 12 s, forme dorée.",
  "LV": "LV",
  "FÜTTERN": "NOURRIR",
  "Satt und mythisch – mehr geht nicht.": "Repu et mythique – impossible de faire mieux.",
  "Übriges Material wird zu Erfahrung. Leibspeise: {mat} (doppelte EP).": "Les matériaux en trop deviennent de l'expérience. Plat préféré : {mat} (XP doublée).",
  "FARBE": "COULEUR",
  "Jede Entwicklungsstufe schaltet eine neue Farbe frei.": "Chaque stade d'évolution débloque une nouvelle couleur.",
  "FÄHIGKEITEN": "COMPÉTENCES",
  "Keine Mutation. Mutationen entstehen selten beim Schlüpfen und öfter bei der Zucht – Glück der Eltern und mutierte Eltern helfen.": "Aucune mutation. Les mutations apparaissent rarement à l'éclosion et plus souvent à l'élevage – la chance des parents et des parents mutants y aident.",
  "Aus der Zucht · Generation {n}": "Issu de l'élevage · génération {n}",
  "Wild geschlüpft – die Gene sind ein Zufallsgeschenk.": "Éclos à l'état sauvage – ses gènes sont un cadeau du hasard.",
  "GENE · SUMME {n}/500": "GÈNES · TOTAL {n}/500",
  "Gene erben sich bei der Zucht: Mittel der Eltern, dazu etwas Zufall. Gute Paare machen bessere Kinder.": "Les gènes se transmettent à l'élevage : moyenne des parents, plus un peu de hasard. Les bons couples font de meilleurs petits.",
  "MUTATION": "MUTATION",
  "HERKUNFT": "ORIGINE",
  "ENTDECKTE MUTATIONEN {n}/{max}": "MUTATIONS DÉCOUVERTES {n}/{max}",
  "Ablegen": "Retirer",
  "Leer": "Vide",
  "Noch leer. Begleiter-Ausrüstung fällt manchmal von Gegnern, wenn dein Begleiter dabei ist – oder Gunda fertigt sie dir an.": "Encore vide. L'équipement de compagnon tombe parfois des ennemis quand ton compagnon t'accompagne – ou Gunda te le fabrique.",
  "Tauschen": "Échanger",
  "Zerlegen (+{g} Gold)": "Démonter (+{g} or)",
  "Fertigen": "Fabriquer",
  "ALLE BONI (TALENTE, AUSRÜSTUNG, MUTATION)": "TOUS LES BONUS (TALENTS, ÉQUIPEMENT, MUTATION)",
  "LAGER {n}/{max}": "ENTREPÔT {n}/{max}",
  "GUNDA FERTIGT": "GUNDA FABRIQUE",
  "Stufe {lv} wie dein Held, Seltenheit ist Glückssache. Halsband: Angriff · Panzer: Schutz für dich · Talisman: Magie und Beute.": "Niveau {lv} comme ton héros, la rareté est une question de chance. Collier : attaque · Carapace : protection pour toi · Talisman : magie et butin.",
  "je Rang": "par rang",
  "Braucht {n} Punkte in {b}": "Requiert {n} points en {b}",
  "Freie Punkte: {n} · 1 Punkt, dazu einer je 2 Level": "Points libres : {n} · 1 point, plus un tous les 2 niveaux",
  "Zurücksetzen ({gold} Gold)": "Réinitialiser ({gold} or)",
  "Sammler: „Große Taschen“ gibt deinem Begleiter mehr Beutelplätze – was im Beutel liegt, überlebt den Tod in den Landen.": "Collecte : « Grandes poches » donne plus de places de sacoche à ton compagnon – ce qu'elle contient survit à la mort dans les Terres.",
  "Sockel {n}": "Châsse {n}",
  "Frei ab LV {lv}": "Débloquée au LV {lv}",
  "Leer – setz unten eine Rune ein.": "Vide – insère une rune ci-dessous.",
  "Herausnehmen": "Retirer",
  "Binden": "Lier",
  "Dein Begleiter wirkt eingesetzte Zauber im Kampf ganz von selbst. Zauberkraft: {p} deiner Waffe (etwa {d} Schaden). Mehr Kraft durch Magie-Gen, Talente und Talisman.": "Ton compagnon lance tout seul les sorts insérés pendant le combat. Puissance des sorts : {p} de ton arme (environ {d} dégâts). Plus de puissance grâce au gène Magie, aux talents et au talisman.",
  "SOCKEL {n}/3": "CHÂSSES {n}/3",
  "ZAUBERRUNEN": "RUNES DE SORT",
  "Runen fallen manchmal von Gegnern, wenn dein Begleiter mitkämpft, oder du bindest sie aus Material. Herausnehmen gibt die Rune zurück.": "Les runes tombent parfois des ennemis quand ton compagnon combat avec toi, ou tu les lies à partir de matériaux. Retirer une rune te la rend.",
  "zuchtreif": "apte à l'élevage",
  "??? (ein Hybrid!)": "??? (un hybride!)",
  "Brutnest voll": "Nid plein",
  "Zu wenig Gold": "Pas assez d'or",
  "Mutation": "Mutation",
  "Erbe möglich": "Transmissible",
  "Gene etwa: {g}": "Gènes env. : {g}",
  "Paaren ({g} Gold)": "Accoupler ({g} or)",
  "Danach ruhen beide Eltern ein paar Stunden. Das Ei kommt ins Brutnest.": "Ensuite, les deux parents se reposent quelques heures. L'œuf va au nid.",
  "{n} weitere Rezepte – entdecke mehr Arten für Hinweise.": "{n} autres recettes – découvre plus d'espèces pour obtenir des indices.",
  "Zwei Begleiter ab LV {lv} legen zusammen ein Ei. Es erbt Gene, manchmal Mutationen – und passende Paare ergeben Hybride.": "Deux compagnons dès le LV {lv} pondent ensemble un œuf. Il hérite de gènes, parfois de mutations – et les bons couples donnent des hybrides.",
  "Elternteil 1": "Parent 1",
  "Partner wählen": "Choisir un partenaire",
  "PARTNER": "PARTENAIRE",
  "BEGLEITER WÄHLEN": "CHOISIR UN COMPAGNON",
  "ZUCHTBUCH · HYBRIDE {n}/{max}": "LIVRE D'ÉLEVAGE · HYBRIDES {n}/{max}",
  "Gerade begleitet dich niemand. Begleiter schlüpfen aus Eiern, die du im Brutnest im Versteck pflegst: Wärme, Futter und Zuwendung.": "Personne ne t'accompagne en ce moment. Les compagnons éclosent des œufs que tu soignes au nid du repaire : chaleur, nourriture et affection.",
  "BEGLEITER": "COMPAGNON",
  "Wärme": "Chaleur",
  "Futter": "Nourriture",
  "Zuwendung": "Affection",
