  "Ab 50 % spürst du, was darin steckt.": "Dès 50 %, tu sens ce qu'il renferme.",
  "Die Schale schimmert seltsam …": "La coquille chatoie étrangement …",
  "Schlüpfen lassen!": "Faire éclore!",
  "Wärmen": "Réchauffer",
  "gratis": "gratuit",
  "Füttern": "Nourrir",
  "Das Nest ist leer.": "Le nid est vide.",
  "Eier gibt es vom ersten Boss der Geschichte, von Bossen, aus der Drachentruhe, aus den Verlorenen Landen und vom Basar.": "Les œufs viennent du premier boss de l'histoire, des boss, du Coffre du dragon, des Terres perdues et du bazar.",
  "Leg ein Ei aus dem Korb ins Nest.": "Place un œuf du panier dans le nid.",
  "Nur im Nest wächst ein Ei.": "Un œuf ne grandit que dans le nid.",
  "Ein Ei ist bereit zum Schlüpfen!": "Un œuf est prêt à éclore!",
  "{n} Eier sind bereit zum Schlüpfen!": "{n} œufs sont prêts à éclore!",
  "Jetzt kommt der große Moment.": "Voici venu le grand moment.",
  "Noch kalt: Wärme, Futter und Zuwendung, dann wächst es.": "Encore froid : chaleur, nourriture et affection, et il grandira.",
  "Ein Ei wächst gerade nicht.": "Un œuf ne grandit plus.",
  "{n} Eier wachsen gerade nicht.": "{n} œufs ne grandissent plus.",
  "Wärmen und Füttern geht mit einem Knopf, Zuwendung gibst du, indem du ein Ei antippst.": "Réchauffer et nourrir se font d'un seul bouton ; pour donner de l'affection, touche un œuf.",
  "Alle Eier wachsen.": "Tous les œufs grandissent.",
  "Versorgt bis {t} – komm dann wieder. Je voller alle drei Leisten, desto schneller.": "Tout va bien jusqu'à {t} – reviens à ce moment-là. Plus les trois jauges sont pleines, plus ça va vite.",
  "Versorgt.": "Tout va bien.",
  "Fürs Füttern fehlt dir: {n}× {mat}. Material gibt es von Gegnern, aus Truhen, der Mine und dem Garten.": "Pour nourrir, il te manque : {n}× {mat}. Les matériaux viennent des ennemis, des coffres, de la mine et du jardin.",
  "Alle wärmen und füttern": "Tout réchauffer et nourrir",
  "Freier Brutplatz – leg ein Ei aus dem Korb hinein.": "Place libre – mets-y un œuf du panier.",
  "Freier Brutplatz": "Place libre",
  "{p} % gebrütet · ": "{p} % couvé · ",
  "Ruht – wächst nur im Nest. Pflegezeit {t}.": "Au repos – ne grandit que dans le nid. Durée de soins : {t}.",
  "Ins Nest": "Au nid",
