  "Leer. Neue Eier kommen ins Nest, solange dort Platz ist.": "Vide. Les nouveaux œufs vont dans le nid tant qu'il y a de la place.",
  "SELTENHEITEN": "RARETÉS",
  "Seltenere Eier brauchen länger und feineres Futter – dafür schlüpfen stärkere Begleiter mit größerem Beutel.": "Les œufs plus rares demandent plus de temps et une nourriture plus fine – mais il en sort des compagnons plus forts, avec un plus grand sac.",
  "Du hast schon {n} Begleiter – lass erst einen frei.": "Tu as déjà {n} compagnons – libères-en d'abord un.",
