  "Man sagt, {name} habe einst {deed}.": "{name}, dit-on, a jadis {deed}.",
  "Seit {n} Wintern haust {name} in {place}.": "Depuis {n} hivers, {name} hante {place}.",
  "{name} sammelt {thing} – und die Knochen derer, die danach fragen.": "{name} collectionne {thing} – et les os de ceux qui posent des questions.",
  "Wer {name} begegnet, hört zuerst {sound}.": "Qui croise {name} entend d'abord {sound}.",
  "Die Kundschafter meiden {place}, seit {name} dort erwacht ist.": "Les éclaireurs évitent {place} : là-bas, {name} a ouvert les yeux.",
  "{name} fürchtet nur eines: {fear}.": "{name} ne craint qu'une chose : {fear}.",
  "Alte Lieder erzählen, {name} sei aus {origin} geboren.": "Selon d'anciens chants, {name} a jailli {origin}.",
  "Auf {name} steht ein Kopfgeld von {g} Gold. Niemand hat es je abgeholt.": "Une prime de {g} pièces d'or est promise pour {name}. Personne ne l'a jamais touchée.",
  "Die Karten des Ordens nennen {place} nur „das Revier von {name}“.": "Sur les cartes de l'Ordre, {place} ne porte qu'une mention : « Ici rôde {name} ».",
  "{name} spricht nie. Doch in {place} flüstern die Steine diesen Namen.": "{name} ne parle jamais. Mais à {place}, les pierres murmurent ce nom.",
  "ein ganzes Heer in Stein verwandelt": "changé une armée entière en pierre",
  "den Mond eine Nacht lang verschluckt": "avalé la lune toute une nuit",
  "drei Könige an einem Tag gestürzt": "renversé trois rois en un seul jour",
  "eine Stadt unter Eis begraben": "enseveli une ville sous la glace",
  "einen Fluss zum Kochen gebracht": "fait bouillir un fleuve",
  "hundert Ritter des Ordens besiegt": "vaincu cent chevaliers de l'Ordre",
  "einen Drachen mit bloßen Händen bezwungen": "terrassé un dragon à mains nues",
  "ein Tor der Alten versiegelt": "scellé une porte des Anciens",
  "die Sonne einen Tag lang verdunkelt": "obscurci le soleil tout un jour",
  "einen Wald in Asche gelegt": "réduit une forêt en cendres",
  "einen Gott betrogen": "trompé un dieu",
  "die Toten eines ganzen Tals geweckt": "réveillé les morts de toute une vallée",
  "eine Flotte im Sturm versenkt": "coulé une flotte dans la tempête",
  "den Schatz eines Zwergenkönigs gestohlen": "volé le trésor d'un roi nain",
  "Kronen gefallener Könige": "des couronnes de rois déchus",
  "Zähne von Drachen": "des dents de dragon",
  "Glocken versunkener Tempel": "des cloches de temples engloutis",
  "zerbrochene Schwerter": "des épées brisées",
  "leuchtende Steine": "des pierres luisantes",
  "die Schädel von Helden": "les crânes de héros",
  "alte Karten der Lande": "de vieilles cartes des Terres",
  "gestohlene Sterne": "des étoiles volées",
  "Federn des Phönix": "des plumes de phénix",
  "die Rüstungen des Ordens": "les armures de l'Ordre",
  "ein fernes Glockenläuten": "un lointain carillon",
  "das Knirschen von Eis": "le craquement de la glace",
  "ein leises Lachen": "un petit rire étouffé",
  "das Rasseln schwerer Ketten": "le cliquetis de lourdes chaînes",
  "das Summen tausender Fliegen": "le bourdonnement de mille mouches",
  "Donner aus klarem Himmel": "un coup de tonnerre dans un ciel clair",
  "ein altes Wiegenlied": "une vieille berceuse",
  "das Knistern von Feuer": "le crépitement d'un feu",
  "Sonnenlicht": "la lumière du soleil",
  "Lieder über Helden": "les chansons de héros",
  "den Klang von Silber": "le tintement de l'argent",
  "Spiegel": "les miroirs",
  "die Stille": "le silence",
  "Kinderlachen": "les rires d'enfants",
  "frisches Wasser": "l'eau fraîche",
  "das Licht der Sterne": "la lumière des étoiles",
  "der ersten Flamme": "de la première flamme",
  "dem Schlamm der Urzeit": "de la boue des premiers âges",
  "einem zerbrochenen Stern": "d'une étoile brisée",
  "dem letzten Atemzug eines Gottes": "du dernier souffle d'un dieu",
  "einem Fluch des Ordens": "d'une malédiction de l'Ordre",
  "der tiefsten Gruft": "de la crypte la plus profonde",
  "einem Riss in der Leere": "d'une faille dans le Néant",
  "den Tränen eines Riesen": "des larmes d'un géant",
