  "Hier ist noch nichts.": "Rien ici pour l'instant.",
  "Höhlen dieses Rangs liegen etwa {d} % tief in den Endlosen Landen.": "Les antres de ce rang se trouvent à environ {d} % de profondeur dans les Terres Infinies.",
