  "Besiege den Boss, um sie zu sehen. Garantiert beim ersten Sieg.": "Bats le boss pour le voir. Garanti à la première victoire.",
  "Übungskampf": "Entraînement",
  "Ohne Beute und ohne Risiko – zum Lernen der Mechaniken.": "Sans butin ni risque – pour apprendre les mécaniques.",
