  "{n} in den Beutel": "{n} dans le sac",
  "{n} ins Lager": "{n} à l'entrepôt",
  "{n} in die Fundkiste am Weltentor": "{n} aux objets trouvés du Portail des mondes",
  "{n} Ei(er) ins Brutnest": "{n} œuf(s) au nid",
  "Kein Platz mehr: für {n} Gold verkauft": "Plus de place : vendu pour {n} or",
  "DAS TOR ÖFFNET SICH …": "LE PORTAIL S'OUVRE …",
  "Das Tor flackert – versuch es noch einmal.": "Le portail vacille – réessaie.",
  "Sammle Beute und entkomm durch einen Ausgang – der goldene Pfeil zeigt den Weg.": "Ramasse du butin et échappe-toi par une sortie – la flèche dorée montre le chemin.",
  "Dein letzter Ausflug endete mitten im Kampf – die Lande haben dich verschlungen. Ausrüstung und Rucksack sind verloren.": "Ta dernière expédition s'est terminée en plein combat – les Terres t'ont englouti. Ton équipement et ton sac à dos sont perdus.",
  "Dein letzter Ausflug in die Verlorenen Lande wurde unterbrochen: Der Rucksack ist verloren, deine Ausrüstung vom Aufbruch hast du noch.": "Ta dernière expédition dans les Terres perdues a été interrompue : le sac à dos est perdu, mais tu as encore l'équipement avec lequel tu es parti.",
  "Dein Begleiter hat noch Beute aus den Landen dabei – sie liegt jetzt bei dir.": "Ton compagnon rapportait encore du butin des Terres – il est maintenant à toi.",
  "AUFTRÄGE ERFÜLLT": "MISSIONS ACCOMPLIES",
  "+{n} Ruf": "+{n} de réputation",
  "ENTKOMMEN!": "SORTIE RÉUSSIE!",
  "{t} in den Landen · {k} Gegner besiegt": "{t} dans les Terres · {k} ennemis vaincus",
  "Neue Weltstufe frei: {n}!": "Nouveau palier débloqué : {n}!",
  "BEUTEWERT {n} GOLD": "BUTIN : {n} OR",
  "NEUER BESTWERT": "NOUVEAU RECORD",
  "+{n} RUF": "+{n} RÉP.",
  "IN SICHERHEIT ({n})": "EN SÛRETÉ ({n})",
  "Diesmal mit leeren Händen – aber lebendig.": "Les mains vides cette fois – mais en vie.",
  "Ins Versteck": "Au repaire",
  "Zur Karte": "Vers la carte",
  "{name} ist verletzt und braucht etwa {n} Minuten Ruhe.": "{name} est blessé et a besoin d'environ {n} minutes de repos.",
  "Hardcore kennt keine Gnade. {name} ist in den Verlorenen Landen gefallen und steht nun in der Ruhmeshalle.": "Le Hardcore ne pardonne pas. {name} a péri dans les Terres perdues et figure désormais au Panthéon.",
  "Dein Begleiter hat {n} Dinge ins Lager gerettet.": "Ton compagnon a mis {n} objets à l'abri dans l'entrepôt.",
  "Zum Titel": "Écran titre",
  "GERETTET VON {name}": "SAUVÉ PAR {name}",
  "Die Begleiter-Tasche war leer – nichts wurde gerettet.": "La sacoche du compagnon était vide – rien n'a été sauvé.",
  "Ohne Begleiter wurde nichts gerettet. Ein Begleiter trägt eine Tasche, die deinen Tod übersteht.": "Sans compagnon, rien n'a été sauvé. Un compagnon porte une sacoche qui survit à ta mort.",
  "Du erwachst im Versteck – mit einfacher Ausrüstung. Schmiede neue oder hol sie dir aus Beutel und Lager.": "Tu te réveilles au repaire – avec un équipement de base. Forges-en un nouveau ou reprends-en dans ton sac et ton entrepôt.",
  "Im Versteck erwachen": "Se réveiller au repaire",
  "GEFALLEN IN DEN VERLORENEN LANDEN": "DÉFAITE DANS LES TERRES PERDUES",
  "VERLOREN · {n} GOLD WERT": "PERTES · {n} OR",
  "Nichts.": "Rien.",
  "Kräuter gesammelt: +1 Heiltrank": "Herbes cueillies : +1 potion de soin",
  "Kräuter gesammelt: +{n} LP": "Herbes cueillies : +{n} PV",
  "Verschlossen – du brauchst einen Schlüssel. Elite-Gegner, Lager und Gefallene tragen welche.": "Verrouillé – il te faut une clé. Les ennemis d'élite, les camps et les aventuriers tombés en portent.",
  "Schlüssel benutzt (noch {n})": "Clé utilisée (il en reste {n})",
  "DER FLUCH ERWACHT": "LA MALÉDICTION S'ÉVEILLE",
  "Wächter steigen aus der Truhe!": "Des gardiens surgissent du coffre!",
  "Eine Falle! Weg von der Truhe!": "Un piège! Éloigne-toi du coffre!",
  "Schlüssel gefunden! ({n})": "Clé trouvée! ({n})",
  "ERBSTÜCK GEFUNDEN": "RELIQUE TROUVÉE",
  "Bring es heil zurück – zu Elwa oder durch einen Ausgang.": "Ramène-la intacte – à Elwa ou par une sortie.",
  "Rucksack voll! Wirf etwas weg oder leg es in die Begleiter-Tasche.": "Sac à dos plein! Jette quelque chose ou mets-le dans la sacoche du compagnon.",
  "Tipp: Alles im Rucksack ist verloren, wenn du fällst. Wertvolles in die Begleiter-Tasche legen – Rucksack-Knopf oben rechts.": "Astuce : tout ce qui est dans le sac à dos est perdu si tu tombes. Mets ce qui a de la valeur dans la sacoche du compagnon – bouton du sac à dos en haut à droite.",
  "SET-TEIL!": "PIÈCE D'ENSEMBLE!",
  "LEGENDÄR!": "LÉGENDAIRE!",
  "{rar}: {item} → Rucksack": "{rar} : {item} → sac à dos",
  "Kartenstück! Ein Teil der Karte ist aufgedeckt.": "Fragment de carte! Une partie de la carte est révélée.",
  "Besiege {n} Gegner": "Vaincs {n} ennemis",
  "Öffne {n} Truhen oder Fundstellen": "Ouvre {n} coffres ou caches",
  "Säubere das markierte Lager": "Nettoie le camp marqué",
  "Erlege {name}": "Abats {name}",
  "Bezwinge das Ungeheuer {name}": "Terrasse le monstre {name}",
  "Stelle den Rivalen {name}": "Affronte le rival {name}",
  "Finde das Erbstück im markierten Grab": "Trouve la relique dans la tombe marquée",
  "Bring {n} {mat}": "Rapporte {n} × {mat}",
  "AUFTRAG ERFÜLLT": "MISSION ACCOMPLIE",
  "Belohnung bei Elwa abholen – oder sie kommt beim Ausgang mit.": "Récupère ta récompense auprès d'Elwa – ou elle te sera versée à la sortie.",
  "Der Gesuchte ist hier!": "Ta cible est ici!",
  "Jäger der Leere sind dir auf den Fersen!": "Des chasseurs du Néant sont à tes trousses!",
  "Tipp: Stell dich in den Ausgang und bleib stehen. Gegner in der Nähe unterbrechen die Flucht.": "Astuce : place-toi dans la sortie et ne bouge plus. Les ennemis proches interrompent la fuite.",
  "Das Schlüsseltor öffnet sich!": "Le portail à clé s'ouvre!",
  "Dieses Tor braucht einen Schlüssel.": "Ce portail nécessite une clé.",
  "MONDTOR ÖFFNET IN {n} S": "OUVERTURE DANS {n} S",
  "GEGNER STÖREN DEN AUSGANG!": "DES ENNEMIS GÊNENT LA SORTIE!",
  "UNTERBROCHEN!": "INTERROMPU!",
  "AUSGANG: {n} S": "SORTIE : {n} S",
  "EIN UNGEHEUER ERWACHT": "UN MONSTRE S'ÉVEILLE",
  "{name} streift durch die Lande – sieh auf die Karte und meide es, oder stell dich ihm!": "{name} rôde dans les Terres – regarde la carte et évite-le, ou affronte-le!",
  "Der Boden bebt – {name} ist ganz nah!": "Le sol tremble – {name} est tout proche!",
  "Kämpfen – oder davonlaufen!": "Combats – ou fuis!",
  "{name} ist mit der Beute entkommen.": "{name} s'est enfui avec le butin.",
  "{name} plündert eine Truhe vor deiner Nase!": "{name} pille un coffre sous ton nez!",
  "Rivale {name} greift an – er will deine Beute!": "Le rival {name} attaque – il veut ton butin!",
  "BEUTE GESICHERT": "BUTIN SÉCURISÉ",
  "LAGER GESÄUBERT": "CAMP NETTOYÉ",
  "Die Gegend ist sicherer – sammle, was sie hinterlassen haben.": "Le coin est plus sûr – ramasse ce qu'ils ont laissé.",
  "UNGEHEUER BEZWUNGEN": "MONSTRE TERRASSÉ",
  "Schnapp dir die Beute – und dann nichts wie raus!": "Prends le butin – et file d'ici!",
  "RIVALE BESIEGT": "RIVAL VAINCU",
  "{name} lässt alles fallen, was er gesammelt hat.": "{name} lâche tout ce qu'il a ramassé.",
  "{n} m": "{n} m",
  "SCHLÜSSELTOR": "PORTAIL À CLÉ",
  "MONDTOR · OFFEN": "LUNAIRE · OUVERT",
