  "Tippe etwas an: anlegen, in die Begleiter-Tasche legen oder wegwerfen.": "Touche un objet : l'équiper, le mettre dans la sacoche du compagnon ou le jeter.",
  "In die Begleiter-Tasche": "Dans la sacoche",
