  "{name} bringt das heim – auch wenn du fällst.": "{name} le ramènera – même si tu tombes.",
  "Keine Plätze.": "Aucune place.",
  "Kein Begleiter dabei: Stirbst du, ist alles verloren.": "Aucun compagnon avec toi : si tu meurs, tout est perdu.",
  "Ohne Begleiter-Tasche: Stirbst du, ist alles verloren.": "Sans sacoche de compagnon : si tu meurs, tout est perdu.",
  "RUCKSACK {n}/{max}": "SAC À DOS {n}/{max}",
