  "{n} Dinge weggeworfen": "{n} objets jetés",
  "Ein Rückweg öffnet sich unter deinen Füßen – bleib stehen!": "Un passage de retour s'ouvre sous tes pieds – ne bouge pas!",
  "MITTEN IM KAMPF!": "EN PLEIN COMBAT!",
  "Abbrechen geht nur, wenn dich gerade nichts angreift. Lauf weg oder kämpfe!": "Tu ne peux abandonner que si rien ne t'attaque. Fuis ou combats!",
  "AUSFLUG ABBRECHEN?": "ABANDONNER L'EXPÉDITION?",
  "Der Rucksack bleibt in den Landen. Du behältst die Ausrüstung, mit der du aufgebrochen bist, und alles in der Begleiter-Tasche.": "Le sac à dos reste dans les Terres. Tu gardes l'équipement avec lequel tu es parti et tout ce qui est dans la sacoche du compagnon.",
  "Ja, abbrechen": "Oui, abandonner",
  "Weiter erkunden": "Explorer encore",
  "Ausflug abgebrochen – {n} Dinge sind verloren.": "Expédition abandonnée – {n} objets perdus.",
  "Ausflug abgebrochen.": "Expédition abandonnée.",
  "Ausgang offen": "Sortie ouverte",
  "Mondtor": "Portail lunaire",
  "Schlüsseltor / Goldtruhe": "Portail à clé / Coffre en or",
