  "KARTE · {n}": "CARTE · {n}",
  "Kundschafterin Elwa hat Aufträge für dich – sie wartet am blauen Punkt.": "Elwa l'Éclaireuse a des missions pour toi – elle t'attend au point bleu.",
  "AUFTRÄGE": "MISSIONS",
  "Belohnung: {rep} Ruf, {items}": "Récompense : {rep} de réputation, {items}",
  "Schlüssel": "Clé",
  "Belohnung nehmen": "Réclamer",
  "Tipp: Erfüllte Aufträge zahlen hier – oder automatisch, wenn du lebend durch einen Ausgang gehst.": "Astuce : les missions accomplies sont payées ici – ou automatiquement quand tu franchis une sortie en vie.",
  "„Der Orden braucht Augen hier draußen. Erledige, was du kannst – bezahlt wird, wenn du es mir bringst oder lebend durch ein Tor gehst.“": "« L'Ordre a besoin d'yeux par ici. Fais ce que tu peux – la paie tombe quand tu me l'apportes ou que tu franchis un portail en vie. »",
  "RUF: {n}": "RÉPUTATION : {n}",
  "Nächster Rang: {n} – {d}": "Rang suivant : {n} – {d}",
  "+{n} Ruf bei den Kundschaftern": "+{n} de réputation auprès des éclaireurs",
  "Gib:": "Donne :",
  "Heiltrank": "Potion de soin",
  "Kartenstück": "Fragment de carte",
  "Rückkehrrolle (Ausgang überall, doppelt so lange stehen)": "Parchemin de retour (sortie n'importe où, attente deux fois plus longue)",
  "Bezahlt wird mit dem Gold in deinem Rucksack.": "On paie avec l'or de ton sac à dos.",
  "Das Gold kommt in den Rucksack – raustragen musst du es trotzdem.": "L'or va dans ton sac à dos – mais il faut encore le ramener.",
  "Dein Rucksack ist leer.": "Ton sac à dos est vide.",
  "„Hier draußen zahlt man mit dem, was man trägt. Zeig her, was du hast.“": "« Par ici, on paie avec ce qu'on porte. Montre-moi ce que tu as. »",
  "TAUSCH": "TROC",
  "KAUFEN": "ACHETER",
  "VERKAUFEN": "VENDRE",
  "Rucksack voll!": "Sac à dos plein!",
  "Getauscht: {n}": "Échangé : {n}",
  "„Setz dich ans Feuer. Die Lande nehmen viel – ein bisschen gebe ich zurück.“": "« Assieds-toi près du feu. Les Terres prennent beaucoup – moi, je rends un peu. »",
  "LP {hp}/{max} · Tränke {n}/{m}": "PV {hp}/{max} · Potions {n}/{m}",
  "Wunden versorgen (einmal frei)": "Panser tes plaies (gratuit une fois)",
  "Wunden versorgen ({n} Gold)": "Panser tes plaies ({n} or)",
  "Kräutersegen wirkt noch": "Bénédiction des herbes active",
  "Kräutersegen: 2 Minuten Regeneration ({n} Gold)": "Bénédiction des herbes : 2 minutes de régénération ({n} or)",
  "Vollständig geheilt": "Entièrement soigné",
  "Kräutersegen: Regeneration für 2 Minuten": "Bénédiction des herbes : régénération pendant 2 minutes",
  "Gegnerstufe {n}": "Niveau ennemi {n}",
  "ab Level {n}": "dès le niveau {n}",
  "{n}× aus {t} entkommen": "S'évader {n}× de {t}",
  "Tasche mit {n} Plätzen – was darin liegt, überlebt deinen Tod.": "Sacoche de {n} places – son contenu survit à ta mort.",
  "Hat keine Tasche.": "N'a pas de sacoche.",
  "{n} PLÄTZE": "{n} PLACES",
  "{name} ist verletzt": "{name} est blessé",
  "Kein Begleiter dabei": "Aucun compagnon",
  "Ruht sich noch {n} Minuten im Versteck aus.": "Se repose encore {n} minutes au repaire.",
  "Ohne Begleiter-Tasche ist bei deinem Tod alles verloren.": "Sans sacoche de compagnon, tout est perdu à ta mort.",
  "FUNDKISTE ({n})": "OBJETS TROUVÉS ({n})",
  "Was beim letzten Mal keinen Platz mehr hatte.": "Ce qui n'avait plus de place la dernière fois.",
  "Alles abholen": "Tout récupérer",
  "WELTSTUFE": "PALIER DU MONDE",
  "Glück auf Legendär und Mythisch: ×{n}": "Chance de Légendaire et Mythique : ×{n}",
  "WAS DU RISKIERST · {n} GOLD": "CE QUE TU RISQUES · {n} OR",
  "WAS ÜBERLEBT": "CE QUI SURVIT",
  "Stirbst du, sind Ausrüstung und Rucksack verloren.": "Si tu meurs, ton équipement et ton sac à dos sont perdus.",
  "Nur die Begleiter-Tasche kommt heim – dein Begleiter teleportiert mit dir zurück.": "Seule la sacoche du compagnon revient – ton compagnon se téléporte avec toi.",
  "Raus kommst du nur durch einen Ausgang: hineinstellen und warten.": "Tu ne peux partir que par une sortie : place-toi dedans et attends.",
  "Abbrechen geht nur außerhalb des Kampfes – wer mitten im Kampf das Spiel schließt, fällt.": "On ne peut abandonner qu'hors combat – qui ferme le jeu en plein combat tombe.",
  "Noch {n} Ruf bis {r}: {d}": "Encore {n} de réputation avant {r} : {d}",
  "AUSFLÜGE {n}": "EXPÉDITIONS {n}",
  "ENTKOMMEN {n}": "ÉVASIONS {n}",
  "GEFALLEN {n}": "MORTS {n}",
