  "SCHLÜSSEL {n}": "CLÉS {n}",
  "Betreten: {n}": "Entrer : {n}",
  "Ab Level {n} – dir fehlen noch {m}": "Dès le niveau {n} – il t'en manque {m}",
  "Hinter dem Tor liegen die Verlorenen Lande: die beste Beute – aber wer dort stirbt, verliert, was er trägt.": "Derrière le portail s'étendent les Terres perdues : le meilleur butin – mais qui y meurt perd ce qu'il porte.",
  "DIE VERLORENEN LANDE": "LES TERRES PERDUES",
  "Die beste Beute – aber wer dort stirbt, verliert, was er trägt.": "Le meilleur butin – mais qui y meurt perd ce qu'il porte.",
  "{n} Dinge abgeholt": "{n} objets récupérés",
  "Verlorene Lande": "Terres perdues",
  "ab LV 5": "dès LV 5",
  "Torhüterin Ysra": "Ysra la Gardienne",
  "Hinter dem Tor liegen die Verlorenen Lande. Wer dort fällt, kommt nackt zurück – wenn überhaupt.": "Derrière le portail s'étendent les Terres perdues. Qui y tombe revient nu – s'il revient.",
  "Nimm deinen Begleiter mit. Was in seiner Tasche steckt, bringt er immer heim.": "Emmène ton compagnon. Ce qu'il a dans sa sacoche, il le ramène toujours.",
  "Je länger du bleibst, desto dunkler wird es. Halte immer einen Ausgang im Blick.": "Plus tu restes, plus il fait sombre. Garde toujours une sortie en vue.",
  "Die Kundschafterin Elwa zahlt gut für Aufträge – und ihr Ruf öffnet Türen.": "Elwa l'Éclaireuse paie bien les missions – et ta réputation auprès d'elle ouvre des portes.",
  "Frühbieter": "Lève-tôt",
  "Stetig": "Régulier",
  "Last-Minute": "Dernière minute",
  "Sammler": "Collectionneur",
  "Schnäppchenjäger": "Chasseur d'affaires",
  "Krämer": "Colporteur",
  "Kaufmann": "Négociant",
  "Großhändler": "Grossiste",
  "Handelsherr": "Maître marchand",
  "Gildenmeister": "Maître de guilde",
  "Magnat": "Magnat",
  "Basarfürst": "Prince du bazar",
  "Goldkönig": "Roi de l'or",
  "Legende des Basars": "Légende du bazar",
  "Auktionatorin Hedda": "Hedda la Crieuse",
  "Alles hat seinen Preis, {name}. Die Kunst ist, ihn vor den anderen zu kennen.": "Tout a un prix, {name}. Tout l'art est de le connaître avant les autres.",
  "Kaspar bietet immer in der letzten Minute. Halt die Augen offen.": "Kaspar enchérit toujours à la dernière minute. Garde l'œil ouvert.",
  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Pour vendre aux enchères, il faut de la patience. Pour enchérir, des nerfs d'acier.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "Un légendaire sous sa valeur marchande? Ça arrive. Rarement. Mais ça arrive.",
  "Grimbart sammelt alles, was glänzt – und zahlt dafür fast jeden Preis.": "Grimbart collectionne tout ce qui brille – et il paie presque n'importe quel prix pour ça.",
  "Mein Hammer fällt, wenn die Zeit um ist. Keine Sekunde früher.": "Mon marteau tombe quand le temps est écoulé. Pas une seconde plus tôt.",
  "Marktwert: {n} Gold": "Valeur marchande : {n} or",
  "Handelsrang {n}: {title}! Weniger Gebühr, mehr Plätze.": "Rang marchand {n} : {title}! Moins de commission, plus d'emplacements.",
  "Bauteil für die Schmiede": "Composant pour la forge",
  "Kommt in dein Brutnest. Gut gepflegt schlüpft daraus ein Begleiter.": "Va dans ton nid. Bien soigné, il donnera naissance à un compagnon.",
