  "Die Gerüste dort? Dort bauen wir Schmiede, Labor, Schatzkammer und mehr. Geh hin und sieh, was es kostet.": "Ces échafaudages là-bas? On y bâtira la forge, le labo, la chambre forte et plus encore. Va voir ce que ça coûte.",
  "Am Lagerfeuer kannst du einmal pro Akt rasten. Und das Portal bringt dich zurück zur Weltkarte.": "Au feu de camp, tu peux te reposer une fois par acte. Et le portail te ramène à la carte du monde.",
