  "Dauerhafter Bonus für alle Helden: {bonus}. Schlag die Trainingspuppe, um deinen Schaden pro Sekunde zu sehen.": "Bonus permanent pour tous les héros : {bonus}. Frappe le mannequin pour voir tes dégâts par seconde.",
  "+{n} % Schaden und LP": "+{n} % de dégâts et de PV",
