  "GESCHICHTE": "HISTOIRE",
  "BESTIARIUM": "BESTIAIRE",
  "Chronikseiten findest du in Truhen, bei Elite-Gegnern, Bossen und in Gräbern. Ab Bibliothek-Stufe 3 häufiger.": "Tu trouves des pages de chronique dans les coffres, sur les ennemis d'élite, les boss et dans les tombes. Plus souvent dès la bibliothèque niveau 3.",
  "Prolog": "Prologue",
