  "REINER ZUFALL": "PUR HASARD",
  "GLÜCKSROLLE": "ROULEAU DE LA FORTUNE",
  "Gratis-Dreh der Glückswoche!": "Tour gratuit de la Semaine de la chance!",
  "Gratis drehen!": "Tour gratuit!",
  "Glücksrolle drehen (1 {coin})": "Lancer le rouleau (1 {coin})",
  "1 {coin} kaufen ({gold} Gold)": "Acheter 1 {coin} ({gold} or)",
  "SCHICKSALSTRUHEN": "COFFRES DU DESTIN",
  "Glücksmünzen gibt es von Bossen, Champions, seltenen Truhen, der Tages-Challenge und Schreinen Fortunas. Jede Drehung ist reiner Zufall mit den gezeigten Chancen – Mythisch kann beim ersten Dreh kommen oder erst nach sehr vielen.": "Les pièces de Fortune s'obtiennent sur les boss, les champions, les coffres rares, le défi du jour et les sanctuaires de Fortuna. Chaque tour est un pur hasard avec les chances affichées – le Mythique peut tomber dès le premier tour ou seulement après des centaines.",
  "Alle Kosmetik gesammelt – 4 Glücksmünzen zurück": "Tous les cosmétiques obtenus – 4 pièces de Fortune rendues",
  "Kosmetik: {name} (im Spiegel anlegen)": "Cosmétique : {name} (à équiper au miroir)",
