  "nicht für deine Klasse": "pas pour ta classe",
  "STEUERUNG": "COMMANDES",
  "Linke Seite ziehen: laufen. Angriff halten (3er-Kombo) – über den Knopf wischen zielt von Hand. Rolle, drei Fähigkeiten, Ultimative (goldene Wut-Leiste). Der Trank sitzt links oben. Alle Knöpfe lassen sich unter Einstellungen → Steuerung verschieben.": "Glisse sur la gauche : te déplacer. Maintiens Attaque (combo de 3) – glisse sur le bouton pour viser à la main. Roulade, trois compétences, Ultime (barre de rage dorée). La potion est en haut à gauche. Tous les boutons se déplacent dans Paramètres → Commandes.",
  "WASD laufen · J/Leertaste/Klick angreifen · K/Shift ausweichen · 1 2 3 Fähigkeiten · F Ultimative · H Trank · E Interagieren · C Charakter · Esc Pause": "WASD se déplacer · J/Espace/Clic attaquer · K/Shift esquiver · 1 2 3 compétences · F Ultime · H potion · E interagir · C personnage · Échap pause",
  "Grafik: „16x16 DungeonTileset II“ von 0x72, Zauber-Effekte „Pixel Art Spells“, „Pixel Art Sword Slash“ und Explosionen von OpenGameArt – alle CC0.": "Graphismes : « 16x16 DungeonTileset II » de 0x72, effets de sorts « Pixel Art Spells », « Pixel Art Sword Slash » et explosions d'OpenGameArt – tous en CC0.",
