  "Löschen!": "Effacer!",
  "Spielen": "Jouer",
  "Löschen": "Effacer",
  "SPRACHE": "LANGUE",
  "Der Uralte Drache hat das Weltenfeuer gestohlen. Bau dein Versteck wieder auf, schmiede Klingen aus Mithril, Adamant und Drachenschuppen – und hol dir zurück, was dem Orden gehört.": "Le Dragon Ancien a volé le Feu du Monde. Rebâtis ton repaire, forge des lames de mithril, d'adamant et d'écailles de dragon – et reprends ce qui appartient à l'Ordre.",
